#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"////~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структура работы с задвижкойtypedef struct : public Queue_PRS  {  CShEdg sh;  } Queue_EdgST;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintEdgST(DefinePaint)  {  QueueP(Queue_EdgST);  //  CShEdg& sh = (CShEdg&)PipeSH;  if ( IsTypeOK )    {    if ( !p->m_bPressed )      memcpy( &p->sh, &sh, sizeof( CShEdg ) );    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция посылки сообщенияstatic void fnSendData(void* base,void* pVoid,bool bMessage)  {  ASS( base )  Queue_EdgST* p = (Queue_EdgST*)base;  if ( !ISTypeOK ) return;  //  bool bSend = true;  //  if ( pVoid == &p->sh.setEnable && lstrcmp( p->send.szValue, "Включение" ) == 0 )  {	  if (!p->sh.isElectro)		  bSend=false;  }  if ( bSend )    {    p->send.SetNew( pVoid );    p->pPipe->SendData( p->send, bMessage );    }  p->m_bPressed = !bMessage;  }void FillEdg( SPriborBase* d, void* pp )  {	  d->fnData = fnSendData;	  Queue_EdgST* p = (Queue_EdgST*)pp;		//if ( d->pVoid == &p->sh.State_Flags && lstrcmp( p->send.szValue, "Зажигание_Пилот" ) == 0 )		//	d->pVoid =  &p->bFirePilot;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddEdgST(DefineTegs)  {  //  AddQueueEx(Queue_EdgST);  //  CShEdg sh;  memcpy( &p->sh, &sh, sizeof(CShEdg) );  p->pSH = &p->sh;  //  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintEdgST;  //  AddPribors( def, teg, Buffer, p, &FillEdg, id_Edg );  //  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~